+    }
+  }
+
+  static void destroy(int64_t comm) {
+    delete reinterpret_cast<quickreduce::DeviceComms*>(comm);
+  }
+
+  static int64_t handle_bytes() {
+    return kHandleBytes;
+  }
+};
